import{_ as e,c as s,o,ah as n}from"./chunks/framework.RCw5T9E9.js";const p=JSON.parse('{"title":"Options → AI","description":"","frontmatter":{"title":"Options → AI"},"headers":[],"relativePath":"ai/settings.md","filePath":"ai/settings.md"}'),r={name:"ai/settings.md"};function a(d,t,i,g,h,l){return o(),s("div",null,[...t[0]||(t[0]=[n('<h1 id="options-→-ai" tabindex="-1">Options → AI <a class="header-anchor" href="#options-→-ai" aria-label="Permalink to &quot;Options → AI&quot;">​</a></h1><p><strong>Options → AI</strong> is the section labeled <strong>AI</strong>. The gear on the <a href="/qa-tools/docs/ai/general.html">AI assistant</a> tab opens <strong>Connection</strong>. <strong>Review access</strong> on that tab opens <strong>Agent access</strong>.</p><p>The blocks follow this order: <strong>Connection</strong>, <strong>Models</strong>, <strong>Personalization</strong>, <strong>Agent access</strong>, <strong>Data masking for AI</strong>.</p><p>These choices are stored in this browser, apart from the inspector settings. <strong>Options → Settings management</strong> does not export, import, or reset them. The screen says: <em>Keys stay in this browser and are not included in settings export.</em></p><h2 id="connection" tabindex="-1">Connection <a class="header-anchor" href="#connection" aria-label="Permalink to &quot;Connection&quot;">​</a></h2><p><strong>OpenRouter</strong> is listed first, then <strong>Gemini</strong>. Each line says <strong>your own API key</strong>.</p><p>A saved key is shown as eight dots and its last four characters, with <strong>Remove</strong>. <strong>Remove</strong> clears that key and leaves the provider selected on the AI tab as it is.</p><p>An empty key shows a password field, <strong>OpenRouter API key</strong> or <strong>Gemini API key</strong>, and <strong>Save</strong>. <strong>Save</strong> is disabled while the field is empty or only spaces. The saved value is trimmed. Saving also selects that provider on the AI tab.</p><p>Under OpenRouter: <strong>Get a free key in</strong> <a href="https://openrouter.ai/settings/keys" target="_blank" rel="noreferrer">OpenRouter</a>. Under Gemini: <strong>Get a free key in</strong> <a href="https://aistudio.google.com/apikey" target="_blank" rel="noreferrer">Google AI Studio</a>.</p><p>Until a key is saved, the AI tab uses <strong>Gemini</strong>.</p><h2 id="models" tabindex="-1">Models <a class="header-anchor" href="#models" aria-label="Permalink to &quot;Models&quot;">​</a></h2><p>The provider menu here only chooses whose list to edit. It starts as the provider selected on the AI tab. Changing it does not change that selection.</p><p><strong>Reload the model list</strong> is disabled while the list is loading. When the list is loaded, the right side shows <strong>N of M available</strong>: <strong>M</strong> is the recommended models plus the ones you added, <strong>N</strong> is how many of them are still checked.</p><p>The field <strong>Add or search model</strong> is disabled until that provider has a key. Without a key the line is <strong>Connect OpenRouter above to see its models.</strong> or <strong>Connect Gemini above to see its models.</strong> While the list loads: <strong>Loading models...</strong> A failure shows the error text.</p><p>The dropdown opens on focus. <strong>Escape</strong> or a click outside closes it.</p><ul><li>An empty field lists free models. The hint is <strong>Free models. Type to search paid ones too.</strong></li><li>Any text matches the model name or id, ignoring case, across free and paid models. The hint is <strong>All models of the provider, free and paid.</strong> Free models come first, then the name.</li><li>At most <strong>60</strong> rows are shown. The rest is <strong>N more, refine the search</strong>.</li><li>Nothing matched: <strong>No models found</strong>.</li></ul><p>A row shows the name, the id, and <strong>free</strong> or <strong>paid</strong>. <strong>recommended</strong> models are already in the list; their checkbox is disabled. Checking another model adds it. The AI tab shows added models under <strong>Added</strong>.</p><p>The list under the field is those recommended and added models.</p><ul><li>A checked row is available. Unchecking hides it from the AI tab and from <strong>Auto</strong>. The name is struck through. The status under the name can be <strong>quota used up, resets in …</strong>, <strong>not available for this key</strong>, or <strong>busy, retry in …</strong>. The title is the provider message. <strong>N today</strong> is how many requests that model had today. Badges: <strong>recommended</strong>, <strong>unstable</strong>, <strong>paid</strong>.</li><li>The last checked model cannot be unchecked.</li><li><strong>Remove from the list</strong> is on models that are not recommended. It is disabled for the last checked model. Recommended models stay in the list; unchecking is how they are hidden.</li></ul><h2 id="personalization" tabindex="-1">Personalization <a class="header-anchor" href="#personalization" aria-label="Permalink to &quot;Personalization&quot;">​</a></h2><p><strong>Defaults</strong> is disabled while the block is already at the defaults: tone <strong>Default</strong>, detail <strong>Normal</strong>, routing <strong>Lite</strong>, and an empty style field.</p><p><strong>Base style and tone</strong></p><table tabindex="0"><thead><tr><th>Value</th><th>Hint</th></tr></thead><tbody><tr><td><strong>Default</strong></td><td>Balanced answers</td></tr><tr><td><strong>Professional</strong></td><td>Precise, neutral wording</td></tr><tr><td><strong>Friendly</strong></td><td>Supportive, plain words</td></tr><tr><td><strong>Direct</strong></td><td>Conclusion first, no filler</td></tr><tr><td><strong>Mentor</strong></td><td>Explains the concepts behind the cause</td></tr></tbody></table><p><strong>Answer detail</strong></p><table tabindex="0"><thead><tr><th>Value</th><th>Hint</th></tr></thead><tbody><tr><td><strong>Brief</strong></td><td>Cause, key evidence and the fix in a few lines</td></tr><tr><td><strong>Normal</strong></td><td>What went wrong, the cause, the evidence and the fix</td></tr><tr><td><strong>Detailed</strong></td><td>The whole chain of events, ruled-out causes, steps to reproduce</td></tr></tbody></table><p><strong>Instruction routing</strong></p><table tabindex="0"><thead><tr><th>Value</th><th>Hint</th></tr></thead><tbody><tr><td><strong>Full</strong></td><td>All task instructions in every request. For strong models</td></tr><tr><td><strong>Lite</strong></td><td>Core rules only; the model loads the instructions of the task when needed</td></tr></tbody></table><p><strong>Your style instructions</strong> holds up to <strong>2000</strong> characters. The placeholder is <strong>For example: answer in Russian, end with a short checklist for the bug report</strong>. The counter is <strong>N / 2000</strong>. The text is saved about <strong>400 ms</strong> after the last change. <strong>Defaults</strong> during that wait can be overwritten by the pending save, so the cleared text comes back.</p><h2 id="agent-access" tabindex="-1">Agent access <a class="header-anchor" href="#agent-access" aria-label="Permalink to &quot;Agent access&quot;">​</a></h2><p>The description is <strong>What the assistant may read and send to the provider.</strong> <strong>Defaults</strong> restores the values below and is disabled while they are already set.</p><p><strong>Attach the logs digest to questions</strong> — hint <strong>A short summary of errors and the timeline.</strong> <strong>Allowed</strong> by default. <strong>Off</strong> sends the question without that summary. The first step of the answer then says <strong>no logs digest (turned off)</strong>.</p><p><strong>Tools.</strong> Each group is <strong>Allowed</strong>, <strong>Ask each time</strong>, or <strong>Off</strong>. The default is <strong>Ask each time</strong>. <strong>Ask each time</strong> uses the confirmation on the <a href="/qa-tools/docs/ai/general.html">AI assistant</a> tab. <strong>Allowed</strong> runs the tool without asking. <strong>Off</strong> does not give that group to the assistant. Reading this documentation stays available.</p><table tabindex="0"><thead><tr><th>Group</th><th>Hint</th></tr></thead><tbody><tr><td><strong>Logs</strong></td><td>Event details and search over the captured logs</td></tr><tr><td><strong>Page code</strong></td><td>List, read and search the scripts of the page and their source maps</td></tr><tr><td><strong>Live page</strong></td><td>Find elements on the page, why they are disabled or hidden, their components, handler code and the current store state</td></tr></tbody></table><p><strong>Data in the logs.</strong> Each line is <strong>Allowed</strong> or <strong>Off</strong>. All three are <strong>Allowed</strong> by default. <strong>Off</strong> replaces the hidden part with <code>[hidden by AI access settings]</code>. Store, props, emit and action values that are off become a type in brackets, such as <code>[string]</code>, while names and paths stay.</p><table tabindex="0"><thead><tr><th>Line</th><th>Hint</th></tr></thead><tbody><tr><td><strong>Request and response headers</strong></td><td>Sensitive headers stay masked</td></tr><tr><td><strong>Request / response bodies and WebSocket messages</strong></td><td></td></tr><tr><td><strong>Values of store state, props, emits and actions</strong></td><td>Off: only names, paths and types</td></tr></tbody></table><h2 id="data-masking-for-ai" tabindex="-1">Data masking for AI <a class="header-anchor" href="#data-masking-for-ai" aria-label="Permalink to &quot;Data masking for AI&quot;">​</a></h2><p>This list is applied when data is sent to the provider. It does not change the <strong>Logs</strong> tab or an HTML report. The Logs mask still runs first. See <a href="/qa-tools/docs/logs/settings.html#data-masking">Data masking</a> for how a fragment matches a key and for <code>[MASKED]</code>, <code>[MASKED JWT]</code>, <code>Bearer [MASKED]</code> and <code>[MASKED CARD]</code>.</p><p>The text under the title: <strong>Values with matching names in objects, headers, URLs, and code are sent as [MASKED].</strong></p><p><strong>Mask sensitive data</strong> is the value-pattern checkbox. It is on by default. While it is off, only the key list is applied.</p><p>The column is <strong>Key contains</strong>. The empty table says <strong>No keys — only value patterns are masked</strong>. The placeholder is <strong>Key fragment, e.g. x-client-secret</strong>. <strong>Add</strong> or <strong>Enter</strong> trims the fragment. An empty value shows <strong>Key cannot be empty</strong>. The same fragment, ignoring case, shows <strong>This key is already in the list</strong>. The row menu is <strong>Delete</strong>. Clicking a row does nothing.</p><p>The default fragments are the <a href="/qa-tools/docs/logs/settings.html#data-masking">Logs list</a> plus <code>passcode</code>, <code>auth</code>, <code>bearer</code>, <code>jwt</code>, <code>credential</code>, <code>session</code>, <code>csrf</code>, <code>xsrf</code>, <code>signature</code>, <code>accesskey</code>, <code>passphrase</code>.</p><p><code>passcode</code> is put back if the saved list does not already contain it. <strong>Delete</strong> on that row does not keep it removed.</p><p><strong>Defaults</strong> restores the key list and turns <strong>Mask sensitive data</strong> on. The button stays enabled when the list is already the default.</p>',43)])])}const m=e(r,[["render",a]]);export{p as __pageData,m as default};
